import { SentenceRange } from "./getSentenceRanges.ts"

// NOTE: This code was generated by an LLM. It has been reviewed by
// human software engineers, but it should be treated with caution.

/** A "slot" is a sentence that needs to be synthesised. */
type Slot = { chapterId: string; id: number }

/** An anchor is a time+file position bounding a gap. */
type Anchor = { time: number; audiofile: string }

/**
 * Maps a slot to the character length of its sentence text, used to weight
 * how much of a gap's time it should occupy. Keyed by `${chapterId}\0${id}`.
 * Slots missing from this map (or with a non-positive length) fall back to
 * a weight of 1, i.e. even division, same as before this map existed.
 */
export type SentenceLengths = Record<string, number>

export function slotKey(slot: Slot): string {
  return `${slot.chapterId}\0${slot.id}`
}

function slotWeight(slot: Slot, sentenceLengths: SentenceLengths): number {
  const length = sentenceLengths[slotKey(slot)]
  return length && length > 0 ? length : 1
}

/**
 * Divide slots across a time span [left.time, right.time], proportionally
 * to each slot's weight (falling back to even division when weights are
 * unavailable). Without this weighting, a 5-word sentence and a 40-word
 * sentence landing in the same gap would get identical durations, which is
 * what previously produced visibly wrong (early/late) highlighting for any
 * interpolated stretch.
 *
 * When the left and right anchors are in different audio files the available
 * time is split into two segments:
 *   - left segment : [left.time,  fileDuration(left.audiofile)] in left.audiofile
 *   - right segment: [0,          right.time]                   in right.audiofile
 *
 * Slots are distributed between the two segments in proportion to the
 * available time in each, unless the gap spans a chapter boundary
 * (`chapterSplit` is the number of slots that belong to the earlier
 * chapter), in which case each chapter's slots stay with its own file. If all
 * the time is on one side every slot goes there.
 */
function buildGapRanges(
  slots: Slot[],
  left: Anchor,
  right: Anchor,
  audioFileDurations: Record<string, number>,
  sentenceLengths: SentenceLengths,
  chapterSplit: number | null,
): SentenceRange[] {
  const n = slots.length
  if (n === 0) return []

  const weights = slots.map((slot) => slotWeight(slot, sentenceLengths))

  if (left.audiofile === right.audiofile) {
    const span = right.time - left.time
    const totalWeight = weights.reduce((a, b) => a + b, 0)
    const result: SentenceRange[] = []
    let cursor = left.time
    for (const [i, slot] of slots.entries()) {
      const start = cursor
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      const end = start + (span * weights[i]!) / totalWeight
      result.push(
        new SentenceRange(slot.id, slot.chapterId, [
          { audiofile: left.audiofile, start, end },
        ]),
      )
      cursor = end
    }
    return result
  }

  const leftDuration = audioFileDurations[left.audiofile] ?? left.time
  const leftAvail = leftDuration - left.time
  const rightAvail = right.time
  const total = leftAvail + rightAvail
  const totalWeight = weights.reduce((a, b) => a + b, 0)

  let n1: number
  if (chapterSplit !== null && leftAvail > 0 && rightAvail > 0) {
    // A chapter boundary that coincides with a file boundary
    n1 = chapterSplit
  } else {
    // Weight assigned to the left vs right segment, proportional to available
    // time in each.
    const leftWeightShare =
      total > 0 ? totalWeight * (leftAvail / total) : totalWeight

    n1 = 0
    let accumulatedWeight = 0
    while (
      n1 < n &&
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      accumulatedWeight + weights[n1]! / 2 <= leftWeightShare
    ) {
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      accumulatedWeight += weights[n1]!
      n1++
    }
  }
  const n2 = n - n1

  const result: SentenceRange[] = []

  if (n1 > 0) {
    const leftSlots = slots.slice(0, n1)
    const leftWeights = weights.slice(0, n1)
    const leftTotalWeight = leftWeights.reduce((a, b) => a + b, 0)
    let cursor = left.time
    for (const [i, slot] of leftSlots.entries()) {
      const start = cursor
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      const end = start + (leftAvail * leftWeights[i]!) / leftTotalWeight
      result.push(
        new SentenceRange(slot.id, slot.chapterId, [
          { audiofile: left.audiofile, start, end },
        ]),
      )
      cursor = end
    }
  }

  if (n2 > 0) {
    const rightSlots = slots.slice(n1)
    const rightWeights = weights.slice(n1)
    const rightTotalWeight = rightWeights.reduce((a, b) => a + b, 0)
    let cursor = 0
    for (const [i, slot] of rightSlots.entries()) {
      const start = cursor
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      const end = start + (rightAvail * rightWeights[i]!) / rightTotalWeight
      result.push(
        new SentenceRange(slot.id, slot.chapterId, [
          { audiofile: right.audiofile, start, end },
        ]),
      )
      cursor = end
    }
  }

  return result
}

/**
 * Given a sequence of sentence ranges from an entire book,
 * ordered by occurrence in audio, interpolates sentence ranges
 * to fill any gaps.
 *
 * A gap may be:
 *   - A non-linearity between two sequential sentence ranges
 *     in the same chapter, e.g. chapter001#0 -> chapter001#3
 *   - A chapter whose sentence ranges start at a number greater
 *     than 0, e.g. chapter001#330 -> chapter002#2
 *   - A chapter whose sentence ranges end at a number lower
 *     than the total number of sentences in that chapter,
 *     e.g. chapter001#325 -> chapter002#0, where
 *     chapterSentenceCounts["chapter001"] === 330
 */
export function interpolateSentenceRanges(
  sentenceRanges: SentenceRange[],
  chapterSentenceCounts: Record<string, number>,
  audioFileDurations: Record<string, number>,
  sentenceLengths: SentenceLengths = {},
): SentenceRange[] {
  if (sentenceRanges.length === 0) return []

  const result: SentenceRange[] = []

  // Sentences before the very first known sentence in its chapter.
  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
  const first = sentenceRanges[0]!
  if (first.id > 0) {
    const slots: Slot[] = Array.from({ length: first.id }, (_, i) => ({
      chapterId: first.chapterId,
      id: i,
    }))
    const left: Anchor = { time: 0, audiofile: first.first.audiofile }
    const right: Anchor = {
      time: first.first.start,
      audiofile: first.first.audiofile,
    }
    result.push(
      ...buildGapRanges(
        slots,
        left,
        right,
        audioFileDurations,
        sentenceLengths,
        null,
      ),
    )
  }

  result.push(first)

  for (let idx = 1; idx < sentenceRanges.length; idx++) {
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const prev = sentenceRanges[idx - 1]!
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const curr = sentenceRanges[idx]!

    const left: Anchor = {
      time: prev.last.end,
      audiofile: prev.last.audiofile,
    }
    const right: Anchor = {
      time: curr.first.start,
      audiofile: curr.first.audiofile,
    }

    const gapSlots: Slot[] = []
    let chapterSplit: number | null = null

    if (prev.chapterId === curr.chapterId) {
      for (let id = prev.id + 1; id < curr.id; id++) {
        gapSlots.push({ chapterId: prev.chapterId, id })
      }
    } else {
      // Trailing sentences missing from the end of prev's chapter.
      const prevTotal = chapterSentenceCounts[prev.chapterId] ?? prev.id + 1
      for (let id = prev.id + 1; id < prevTotal; id++) {
        gapSlots.push({ chapterId: prev.chapterId, id })
      }
      chapterSplit = gapSlots.length
      // Leading sentences missing from the start of curr's chapter.
      for (let id = 0; id < curr.id; id++) {
        gapSlots.push({ chapterId: curr.chapterId, id })
      }
    }

    if (gapSlots.length > 0) {
      result.push(
        ...buildGapRanges(
          gapSlots,
          left,
          right,
          audioFileDurations,
          sentenceLengths,
          chapterSplit,
        ),
      )
    }

    result.push(curr)
  }

  // Sentences missing from the end of the last known sentence's chapter.
  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
  const last = sentenceRanges[sentenceRanges.length - 1]!
  const lastTotal = chapterSentenceCounts[last.chapterId] ?? last.id + 1

  if (last.id < lastTotal - 1) {
    const slots: Slot[] = Array.from(
      { length: lastTotal - 1 - last.id },
      (_, i) => ({ chapterId: last.chapterId, id: last.id + 1 + i }),
    )
    const fileEnd = audioFileDurations[last.last.audiofile] ?? last.last.end
    const left: Anchor = {
      time: last.last.end,
      audiofile: last.last.audiofile,
    }
    const right: Anchor = { time: fileEnd, audiofile: last.last.audiofile }
    result.push(
      ...buildGapRanges(
        slots,
        left,
        right,
        audioFileDurations,
        sentenceLengths,
        null,
      ),
    )
  }

  return result
}
